/* Source monster base stats for new encounters only; old saved battles keep their balance. */
(function(g){'use strict';const fields={hp:[1,10000],mp:[0,10000],attack:[0,2000],defense:[-100,100],magicDefense:[0,1000],damageReduction:[0,1000],accuracy:[-100,100],evasion:[-100,100],level:[1,1000]},need=(v,s)=>{if(!v)throw Error(s);};
function validate(v){need(v&&v.v===1&&Object.entries(fields).every(([k,[lo,hi]])=>Number.isFinite(v[k])&&v[k]>=lo&&v[k]<=hi),'ค่าสถานะพื้นฐานมอนสเตอร์ไม่ถูกต้อง');return v;}
function compile(r){if(!r||r.kind!=='monster'||r.enabled===false)return null;const p={v:1};for(const [k,[lo,hi]]of Object.entries(fields)){const value=r[k]===undefined&&k==='mp'?0:r[k];if(!Number.isFinite(value)||value<lo||value>hi)return null;p[k]=value;}return p;}
function initialize(e,rows){need(e.design===1&&e.tactical&&e.status==='active'&&e.round===1,'ใช้ค่าสถานะใหม่ได้เฉพาะตอนเริ่มสนาม');const plans=[];for(const u of e.units.filter(u=>u.side==='enemy'&&u.catalogStats===undefined)){const r=rows.find(r=>r.kind==='monster'&&r.id===u.monsterId);if(!r||r.enabled===false)continue;const p=compile(r);need(p,'ค่าสถานะมอนสเตอร์ '+r.name+' ไม่ครบหรือเกินขอบเขตที่รองรับ');plans.push({u,p});}for(const {u,p} of plans){u.catalogStats=p;u.hp=u.maxHp=p.hp;u.mana=u.maxMana=p.mp;u.attack=p.attack;u.armor=0;}return e;}
function adjustments(u){const p=u.side==='enemy'?u.catalogStats:null;return p?{accuracy:(p.accuracy-10)*.01,defense:(p.defense-10)*.05,evasion:p.evasion*.01,physicalReduction:p.damageReduction,magicReduction:p.magicDefense}:{accuracy:0,defense:0,evasion:0,physicalReduction:0,magicReduction:0};}
function describe(p){return 'HP '+p.hp+' • MP '+p.mp+' • ATK โจมตีปกติ '+p.attack+' • Defense '+p.defense+' (เทียบค่ากลาง 10) • Accuracy '+p.accuracy+' (เทียบค่ากลาง 10) • Evasion '+p.evasion+' • ลดดาเมจกายภาพ '+p.damageReduction+' • ลดดาเมจเวท '+p.magicDefense+' • ไม่รวม Passive';}
const api={compile,validate,initialize,adjustments,describe};g.DecideMonsterStats=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
